  // Quad-precision variants.
  // The original Fortran module notes these are broken outside gfortran (no
  // standard c_float128 binding). Guard with __GNUC__ as in the qcdloop library.
#ifdef __GNUC__
  __complex__ __float128 qli1q(__float128 m1, __float128 mu2, int ep);
  __complex__ __float128 qli2q(__float128 p1, __float128 m1, __float128 m2,
                     __float128 mu2, int ep);
  __complex__ __float128 qli3q(__float128 p1, __float128 p2, __float128 p3,
                     __float128 m1, __float128 m2, __float128 m3,
                     __float128 mu2, int ep);
  __complex__ __float128 qli4q(__float128 p1, __float128 p2, __float128 p3, __float128 p4,
                     __float128 s12, __float128 s23,
                     __float128 m1, __float128 m2, __float128 m3, __float128 m4,
                     __float128 mu2, int ep);
  __complex__ __float128 qli1qc(__complex__ __float128 m1, __float128 mu2, int ep);
  __complex__ __float128 qli2qc(__float128 p1, __complex__ __float128 m1, __complex__ __float128 m2,
                      __float128 mu2, int ep);
  __complex__ __float128 qli3qc(__float128 p1, __float128 p2, __float128 p3,
                      __complex__ __float128 m1, __complex__ __float128 m2, __complex__ __float128 m3,
                      __float128 mu2, int ep);
  __complex__ __float128 qli4qc(__float128 p1, __float128 p2, __float128 p3, __float128 p4,
                      __float128 s12, __float128 s23,
                      __complex__ __float128 m1, __complex__ __float128 m2, __complex__ __float128 m3,
                      __complex__ __float128 m4, __float128 mu2, int ep);
#endif // __GNUC__

} // extern "C"

