  // Quad-precision variants (qli*q, qli*qc) are omitted from the C++ header.
  // They require __float128 / __complex128 which have no portable extern "C"
  // representation in C++ (the original Fortran source notes they are broken
  // outside gfortran).  Fortran callers access them through the mod_qcdloop_c
  // Fortran shim (mod_qcdloop_c.f90) which preserves the full interface block.

} // extern "C"
